import { Router, type IRouter } from "express";
import {
  and,
  db,
  eq,
  inArray,
  countriesTable,
  legacyPaymentAggregatorRoutesTable,
  operatorCatalogTable,
  operatorOtpPoliciesTable,
  operatorPricingRatesTable,
  paymentAggregatorRoutesTable,
  sql,
} from "@workspace/db";
import {
  CreateAdminOperatorBody,
  CreateAdminOperatorResponse,
  DeleteAdminOperatorBody,
  GetAdminOperatorPricingResponse,
  GetPublicPricingResponse,
  UpdateAdminOperatorBody,
  UpdateAdminOperatorPricingBody,
  UpdateAdminOperatorPricingResponse,
  UpdateAdminOperatorResponse,
} from "@workspace/api-zod";
import { recordAdminAudit } from "../lib/admin-audit";
import { operatorLogoUrl, readOperatorLogo } from "../services/operator-logo";
import {
  createOperatorDisplayFields,
  isPricingCategoryId,
  pricingCategories,
  getPricingCountryCatalog,
  type PricingCategoryId,
} from "../lib/operator-pricing-catalog";
import { respondAdminAuthError } from "./admin";

const router: IRouter = Router();
const adminRoutes: IRouter = Router();
const otpCommands: Record<string, string> = {
  "orange-ci": "#144*82# option 2",
};

const operatorMetadataColumns = {
  operatorId: operatorCatalogTable.operatorId,
  countryCode: operatorCatalogTable.countryCode,
  name: operatorCatalogTable.name,
  shortName: operatorCatalogTable.shortName,
  initials: operatorCatalogTable.initials,
  brand: operatorCatalogTable.brand,
  enabled: operatorCatalogTable.enabled,
  depositEnabled: operatorCatalogTable.depositEnabled,
  interNetworkEnabled: operatorCatalogTable.interNetworkEnabled,
  internationalEnabled: operatorCatalogTable.internationalEnabled,
  version: operatorCatalogTable.version,
  updatedAt: operatorCatalogTable.updatedAt,
  hasLogo: sql<boolean>`${operatorCatalogTable.logoData} IS NOT NULL`,
};

type OperatorMetadataRecord = Pick<
  typeof operatorCatalogTable.$inferSelect,
  "operatorId" | "countryCode" | "name" | "shortName" | "initials" | "brand" | "enabled" |
  "depositEnabled" | "interNetworkEnabled" | "internationalEnabled" | "version" | "updatedAt"
> & {
  hasLogo?: boolean;
  logoData?: typeof operatorCatalogTable.$inferSelect.logoData;
};

function toManagedOperator(
  operator: OperatorMetadataRecord,
  rates: Array<typeof operatorPricingRatesTable.$inferSelect> = [],
) {
  const hasLogo = operator.hasLogo ?? Boolean(operator.logoData);
  return {
    operatorId: operator.operatorId,
    countryCode: operator.countryCode,
    name: operator.name,
    shortName: operator.shortName,
    initials: operator.initials,
    brand: operator.brand,
    logoUrl: operatorLogoUrl(operator.operatorId, operator.version, hasLogo),
    enabled: operator.enabled,
    depositEnabled: operator.depositEnabled,
    interNetworkEnabled: operator.interNetworkEnabled,
    internationalEnabled: operator.internationalEnabled,
    version: operator.version,
    updatedAt: operator.updatedAt?.toISOString() ?? null,
    ...(rates.length > 0
      ? {
          rates: rates.map((rate) => ({
            categoryId: rate.categoryId,
            feePercent: rate.feePercent,
            version: rate.version,
            updatedAt: rate.updatedAt?.toISOString() ?? null,
          })),
        }
      : {}),
  };
}

router.get("/operators/:operatorId/logo", async (req, res): Promise<void> => {
  const operatorId = typeof req.params.operatorId === "string" ? req.params.operatorId : "";
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(operatorId)) {
    res.status(404).json({ error: "Logo not found" });
    return;
  }

  try {
    const logo = await readOperatorLogo(operatorId);
    if (!logo) {
      res.status(404).json({ error: "Logo not found" });
      return;
    }
    res.setHeader("Content-Type", logo.contentType);
    res.setHeader("Content-Length", logo.bytes.length);
    res.setHeader("X-Content-Type-Options", "nosniff");
    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
    res.setHeader("ETag", logo.etag);
    if (req.get("if-none-match")?.split(/\s*,\s*/).includes(logo.etag)) {
      res.status(304).end();
      return;
    }
    res.status(200).send(logo.bytes);
  } catch (error) {
    req.log.error({ err: error }, "Operator logo lookup failed");
    res.status(503).json({ error: "Operator logo unavailable" });
  }
});

router.get("/pricing", async (req, res): Promise<void> => {
  try {
    const [operators, rates, otpPolicies, countries] = await Promise.all([
      db.select(operatorMetadataColumns).from(operatorCatalogTable),
      db.select().from(operatorPricingRatesTable),
      db.select().from(operatorOtpPoliciesTable),
      getPricingCountryCatalog(),
    ]);
    const rateRowsByOperator = new Map<string, typeof rates>();
    for (const rate of rates) {
      const operatorRates = rateRowsByOperator.get(rate.operatorId) ?? [];
      operatorRates.push(rate);
      rateRowsByOperator.set(rate.operatorId, operatorRates);
    }
    const otpByOperator = new Map(
      otpPolicies.map((policy) => [`${policy.countryCode}:${policy.operatorId}`, policy.requiresOtp]),
    );

    const publicOperators = operators
      .filter((operator) => operator.enabled)
      .sort((left, right) => {
        const countryOrder = left.countryCode.localeCompare(right.countryCode);
        return countryOrder || left.name.localeCompare(right.name, "fr");
      })
      .map((operator) => {
        const fees: Partial<Record<PricingCategoryId, number>> = {};
        for (const rate of rateRowsByOperator.get(operator.operatorId) ?? []) {
          if (isPricingCategoryId(rate.categoryId) && rate.feePercent !== null) {
            fees[rate.categoryId] = rate.feePercent / 100;
          }
        }

        return {
          id: operator.operatorId,
          countryId: operator.countryCode,
          name: operator.name,
          shortName: operator.shortName,
          initials: operator.initials,
          brand: operator.brand,
          logoUrl: operatorLogoUrl(operator.operatorId, operator.version, operator.hasLogo),
          requiresOtp:
            otpByOperator.get(`${operator.countryCode}:${operator.operatorId}`) ?? true,
          otpCommand: otpCommands[operator.operatorId] ?? null,
          operations: {
            deposit: Boolean(countries.find((country) => country.id === operator.countryCode
              && country.enabled && country.operations.deposit)) && operator.depositEnabled,
            interNetwork: Boolean(countries.find((country) => country.id === operator.countryCode
              && country.enabled && country.operations.interNetwork)) && operator.interNetworkEnabled,
            international: Boolean(countries.find((country) => country.id === operator.countryCode
              && country.enabled && country.operations.international)) && operator.internationalEnabled,
          },
          fees,
        };
      });

    res.setHeader("Cache-Control", "no-store");
    res.json(
      GetPublicPricingResponse.parse({
        categories: pricingCategories,
        countries: countries.map(({ id, name, dialCode, initials, flag, enabled, minPhoneDigits, maxPhoneDigits, operations }) => ({
          id,
          name,
          dialCode,
          initials,
          flag,
          enabled,
          minPhoneDigits,
          maxPhoneDigits,
          operations,
        })),
        operators: publicOperators,
      }),
    );
  } catch (error) {
    req.log.error({ err: error }, "Public operator pricing lookup failed");
    res.status(503).json({ error: "Pricing catalog unavailable" });
  }
});

adminRoutes.get("/operator-pricing", async (req, res): Promise<void> => {
  const adminUserId = respondAdminAuthError(req, res);
  if (!adminUserId) return;

  try {
    const [operators, rates, countryCatalog] = await Promise.all([
      db.select(operatorMetadataColumns).from(operatorCatalogTable),
      db.select().from(operatorPricingRatesTable),
      getPricingCountryCatalog(),
    ]);
    const rateRowsByOperator = new Map<string, typeof rates>();
    for (const rate of rates) {
      const operatorRates = rateRowsByOperator.get(rate.operatorId) ?? [];
      operatorRates.push(rate);
      rateRowsByOperator.set(rate.operatorId, operatorRates);
    }
    const countries = countryCatalog.map((country) => ({
      countryCode: country.countryCode,
      countryName: country.countryName,
      phonePrefix: country.phonePrefix,
      initials: country.initials,
      flag: country.flag,
      enabled: country.enabled,
      operations: country.operations,
      operators: operators
        .filter((operator) => operator.countryCode === country.countryCode)
        .sort((left, right) => left.name.localeCompare(right.name, "fr"))
        .map((operator) =>
          toManagedOperator(operator, rateRowsByOperator.get(operator.operatorId) ?? []),
        ),
    }));

    await recordAdminAudit({
      adminUserId,
      action: "view_operator_pricing",
      resourceType: "operator_pricing",
      resourceId: "catalog",
    });

    res.setHeader("Cache-Control", "no-store");
    res.json(GetAdminOperatorPricingResponse.parse({ categories: pricingCategories, countries }));
  } catch (error) {
    req.log.error({ err: error }, "Admin operator pricing lookup failed");
    res.status(503).json({ error: "Administrator storage unavailable" });
  }
});

adminRoutes.post("/operators", async (req, res): Promise<void> => {
  const adminUserId = respondAdminAuthError(req, res, "mutate");
  if (!adminUserId) return;

  const body = CreateAdminOperatorBody.safeParse(req.body);
  if (!body.success || body.data.reason.trim().length < 3) {
    res.status(400).json({ error: "Invalid operator data or audit reason" });
    return;
  }

  const slug = body.data.name
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48)
    .replace(/-+$/g, "");
  if (slug.length < 1) {
    res.status(400).json({ error: "Operator name must include a letter or number" });
    return;
  }

  const operatorId = `${slug}-${body.data.countryCode}`;
  const display = createOperatorDisplayFields(body.data.name.trim(), body.data.brand);

  try {
    const [knownCountry] = await db
      .select({ countryCode: countriesTable.countryCode })
      .from(countriesTable)
      .where(eq(countriesTable.countryCode, body.data.countryCode))
      .limit(1);
    if (!knownCountry) {
      res.status(404).json({ error: "Country not found" });
      return;
    }

    const created = await db.transaction(async (tx) => {
      const [operator] = await tx
        .insert(operatorCatalogTable)
        .values({
          operatorId,
          countryCode: body.data.countryCode,
          name: body.data.name.trim(),
          ...display,
          brand: body.data.brand,
          enabled: false,
          depositEnabled: false,
          interNetworkEnabled: false,
          internationalEnabled: false,
          version: 1,
          createdBy: adminUserId,
          updatedBy: adminUserId,
        })
        .onConflictDoNothing()
        .returning();

      if (!operator) return undefined;

      await tx.insert(operatorPricingRatesTable).values(
        pricingCategories.map((category) => ({
          operatorId,
          countryCode: body.data.countryCode,
          categoryId: category.id,
          feePercent: null,
          version: 1,
          createdBy: adminUserId,
          updatedBy: adminUserId,
        })),
      );
      await recordAdminAudit(
        {
          adminUserId,
          action: "create_operator",
          resourceType: "operator",
          resourceId: operatorId,
          reason: body.data.reason.trim(),
        },
        tx,
      );
      return operator;
    });

    if (!created) {
      res.status(409).json({ error: "An operator with this name already exists in the country" });
      return;
    }

    res.status(201).json(
      CreateAdminOperatorResponse.parse(toManagedOperator(created)),
    );
  } catch (error) {
    req.log.error({ err: error }, "Admin operator creation failed");
    res.status(503).json({ error: "Administrator storage unavailable" });
  }
});

adminRoutes.patch("/operators/:operatorId", async (req, res): Promise<void> => {
  const adminUserId = respondAdminAuthError(req, res, "mutate");
  if (!adminUserId) return;

  const body = UpdateAdminOperatorBody.safeParse(req.body);
  const operatorId = typeof req.params.operatorId === "string" ? req.params.operatorId : "";
  if (!body.success || body.data.reason.trim().length < 3 || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(operatorId)) {
    res.status(400).json({ error: "Invalid operator data or audit reason" });
    return;
  }

  try {
    const [existing] = await db
      .select()
      .from(operatorCatalogTable)
      .where(eq(operatorCatalogTable.operatorId, operatorId))
      .limit(1);
    if (!existing) {
      res.status(404).json({ error: "Operator not found" });
      return;
    }

    const display = createOperatorDisplayFields(body.data.name.trim(), body.data.brand);
    const updated = await db.transaction(async (tx) => {
      const [operator] = await tx
        .update(operatorCatalogTable)
        .set({
          name: body.data.name.trim(),
          ...display,
          brand: body.data.brand,
          enabled: body.data.enabled,
          depositEnabled: body.data.depositEnabled,
          interNetworkEnabled: body.data.interNetworkEnabled,
          internationalEnabled: body.data.internationalEnabled,
          version: body.data.expectedVersion + 1,
          updatedBy: adminUserId,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(operatorCatalogTable.operatorId, operatorId),
            eq(operatorCatalogTable.version, body.data.expectedVersion),
          ),
        )
        .returning();
      if (!operator) return undefined;

      await recordAdminAudit(
        {
          adminUserId,
          action: "update_operator",
          resourceType: "operator",
          resourceId: operator.operatorId,
          reason: body.data.reason.trim(),
        },
        tx,
      );
      return operator;
    });

    if (!updated) {
      res.status(409).json({ error: "Operator changed since it was loaded" });
      return;
    }

    res.json(UpdateAdminOperatorResponse.parse(toManagedOperator(updated)));
  } catch (error) {
    req.log.error({ err: error }, "Admin operator update failed");
    res.status(503).json({ error: "Administrator storage unavailable" });
  }
});

adminRoutes.delete("/operators/:operatorId", async (req, res): Promise<void> => {
  const adminUserId = respondAdminAuthError(req, res, "mutate");
  if (!adminUserId) return;

  const body = DeleteAdminOperatorBody.safeParse(req.body);
  const operatorId = typeof req.params.operatorId === "string" ? req.params.operatorId : "";
  if (!body.success || body.data.reason.trim().length < 3
    || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(operatorId)) {
    res.status(400).json({ error: "Invalid operator deletion request" });
    return;
  }

  try {
    const deleted = await db.transaction(async (tx) => {
      const [operator] = await tx
        .select()
        .from(operatorCatalogTable)
        .where(eq(operatorCatalogTable.operatorId, operatorId))
        .for("update")
        .limit(1);
      if (!operator) return "missing" as const;
      if (operator.version !== body.data.expectedVersion) return "changed" as const;
      if (
        operator.enabled ||
        operator.depositEnabled ||
        operator.interNetworkEnabled ||
        operator.internationalEnabled
      ) {
        return "referenced" as const;
      }

      const routeReferences = await Promise.all([
        tx.select({ operatorId: paymentAggregatorRoutesTable.operatorId })
          .from(paymentAggregatorRoutesTable)
          .where(eq(paymentAggregatorRoutesTable.operatorId, operator.operatorId))
          .limit(1),
        tx.select({ operatorId: legacyPaymentAggregatorRoutesTable.operatorId })
          .from(legacyPaymentAggregatorRoutesTable)
          .where(eq(legacyPaymentAggregatorRoutesTable.operatorId, operator.operatorId))
          .limit(1),
      ]);
      if (routeReferences.some((rows) => rows.length > 0)) return "referenced" as const;

      await tx.delete(operatorOtpPoliciesTable).where(and(
        eq(operatorOtpPoliciesTable.countryCode, operator.countryCode),
        eq(operatorOtpPoliciesTable.operatorId, operator.operatorId),
      ));
      await tx.delete(operatorPricingRatesTable)
        .where(eq(operatorPricingRatesTable.operatorId, operator.operatorId));

      const [removed] = await tx.delete(operatorCatalogTable).where(and(
        eq(operatorCatalogTable.operatorId, operator.operatorId),
        eq(operatorCatalogTable.version, body.data.expectedVersion),
      )).returning({ operatorId: operatorCatalogTable.operatorId });
      if (!removed) return "changed" as const;

      await recordAdminAudit({
        adminUserId,
        action: "delete_operator",
        resourceType: "operator",
        resourceId: operator.operatorId,
        reason: body.data.reason.trim(),
      }, tx);
      return "deleted" as const;
    });

    if (deleted === "missing") {
      res.status(404).json({ error: "Operator not found" });
      return;
    }
    if (deleted === "changed") {
      res.status(409).json({ error: "Operator changed since it was loaded" });
      return;
    }
    if (deleted === "referenced") {
      res.status(409).json({ error: "Disable the operator and remove its routing before deleting it" });
      return;
    }
    res.status(204).end();
  } catch (error) {
    req.log.error({ err: error }, "Admin operator deletion failed");
    res.status(503).json({ error: "Administrator storage unavailable" });
  }
});

class PricingRateConflictError extends Error {}

adminRoutes.put("/operator-pricing-rates", async (req, res): Promise<void> => {
  const adminUserId = respondAdminAuthError(req, res, "mutate");
  if (!adminUserId) return;

  const body = UpdateAdminOperatorPricingBody.safeParse(req.body);
  if (!body.success || body.data.reason.trim().length < 3) {
    res.status(400).json({ error: "Invalid rates or audit reason" });
    return;
  }

  const { countryCode, categoryId, updates } = body.data;
  if (new Set(updates.map((update) => update.operatorId)).size !== updates.length) {
    res.status(400).json({ error: "Each operator can only appear once in a section update" });
    return;
  }

  try {
    const requestedIds = updates.map((update) => update.operatorId);
    const knownOperators = await db
      .select({ operatorId: operatorCatalogTable.operatorId, countryCode: operatorCatalogTable.countryCode })
      .from(operatorCatalogTable)
      .where(inArray(operatorCatalogTable.operatorId, requestedIds));
    if (
      knownOperators.length !== requestedIds.length ||
      knownOperators.some((operator) => operator.countryCode !== countryCode)
    ) {
      res.status(404).json({ error: "One or more operators are not part of this country" });
      return;
    }

    const updatedRates = await db.transaction(async (tx) => {
      const rows: Array<typeof operatorPricingRatesTable.$inferSelect> = [];
      for (const update of updates) {
        const [rate] = await tx
          .update(operatorPricingRatesTable)
          .set({
            feePercent: update.feePercent,
            version: update.expectedVersion + 1,
            updatedBy: adminUserId,
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(operatorPricingRatesTable.operatorId, update.operatorId),
              eq(operatorPricingRatesTable.countryCode, countryCode),
              eq(operatorPricingRatesTable.categoryId, categoryId),
              eq(operatorPricingRatesTable.version, update.expectedVersion),
            ),
          )
          .returning();
        if (!rate) throw new PricingRateConflictError();
        rows.push(rate);
      }

      await recordAdminAudit(
        {
          adminUserId,
          action: "update_operator_pricing",
          resourceType: "operator_pricing",
          resourceId: `${countryCode}:${categoryId}`,
          reason: body.data.reason.trim(),
        },
        tx,
      );
      return rows;
    });

    res.json(
      UpdateAdminOperatorPricingResponse.parse({
        items: updatedRates.map((rate) => ({
          operatorId: rate.operatorId,
          categoryId: rate.categoryId,
          feePercent: rate.feePercent,
          version: rate.version,
          updatedAt: rate.updatedAt.toISOString(),
        })),
      }),
    );
  } catch (error) {
    if (error instanceof PricingRateConflictError) {
      res.status(409).json({ error: "One or more rates changed since they were loaded" });
      return;
    }
    req.log.error({ err: error }, "Admin operator pricing update failed");
    res.status(503).json({ error: "Administrator storage unavailable" });
  }
});

export { adminRoutes };
export default router;