import { Router, type IRouter } from "express";
import {
  and,
  customerCredentialsTable,
  customerSessionsTable,
  db,
  eq,
  isNull,
  or,
  phoneOtpChallengesTable,
  usersTable,
} from "@workspace/db";
import {
  ResetCustomerPasswordBody,
  ResetCustomerPasswordResponse,
  ResetCustomerPinBody,
  ResetCustomerPinResponse,
} from "@workspace/api-zod";
import {
  clearAuthFailures,
  getCustomerAccessAttemptBucketsForRequest,
  getCustomerLoginEmailAttemptBucket,
  getCustomerAccessPhoneAttemptBucket,
  getCustomerLoginPhoneAttemptBucket,
  getCustomerPinAttemptBucket,
  withAuthAttemptLock,
  withPinAttemptLock,
} from "../lib/customer-auth-rate-limit";
import { hashCustomerSecret } from "../lib/customer-auth-crypto";
import { createSensitiveDataLookupIndex } from "../lib/sensitive-data-crypto";
import {
  verifiedCustomerEmailOtpCondition,
  verifiedCustomerOtpCondition,
} from "../lib/customer-auth-otp";
import { hashSecretForClaimedOtpChallenge } from "../lib/customer-recovery-policy";
import { fingerprint, isTrustedOrigin, requesterAddress } from "../lib/request-security";
import {
  rejectTurnstileRequest,
  verifyTurnstileRequest,
} from "../lib/turnstile";

const router: IRouter = Router();

function safeErrorCode(error: unknown) {
  return typeof error === "object" && error !== null && "code" in error
    ? String((error as { code?: unknown }).code ?? "")
    : "";
}

router.post("/auth/reset-password", async (req, res): Promise<void> => {
  if (!isTrustedOrigin(req)) {
    res.status(403).json({ error: "Origine de requête non autorisée." });
    return;
  }

  const rawTurnstileToken = typeof req.body === "object" && req.body !== null
    ? (req.body as { turnstileToken?: unknown }).turnstileToken
    : undefined;
  if (typeof rawTurnstileToken !== "string" || rawTurnstileToken.length === 0) {
    rejectTurnstileRequest(req, res, {
      success: false,
      category: "missing_token",
      unavailable: false,
    });
    return;
  }

  const parsed = ResetCustomerPasswordBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Vérifiez les informations de récupération." });
    return;
  }

  const turnstile = await verifyTurnstileRequest(
    req,
    parsed.data.turnstileToken,
    "password_reset",
  );
  if (!turnstile.success) {
    rejectTurnstileRequest(req, res, turnstile);
    return;
  }

  const now = new Date();
  try {
    const emailLookupHash = createSensitiveDataLookupIndex(parsed.data.email, "user-email");
    const authAttemptBuckets = [
      getCustomerLoginEmailAttemptBucket(emailLookupHash),
      ...getCustomerAccessAttemptBucketsForRequest(null, requesterAddress(req)),
    ];
    const [availableChallenge] = await db
      .select({ id: phoneOtpChallengesTable.id })
      .from(phoneOtpChallengesTable)
      .where(
        verifiedCustomerEmailOtpCondition(
          parsed.data.challengeId,
          parsed.data.email,
          "password_reset",
          now,
        ),
      )
      .limit(1);
    if (!availableChallenge) {
      res.status(409).json({ error: "La vérification a expiré ou a déjà été utilisée. Demandez un nouveau code." });
      return;
    }

    const result = await withAuthAttemptLock(authAttemptBuckets, async (tx) => {
      const [challenge] = await tx
        .select({ id: phoneOtpChallengesTable.id })
        .from(phoneOtpChallengesTable)
        .where(
          verifiedCustomerEmailOtpCondition(
            parsed.data.challengeId,
            parsed.data.email,
            "password_reset",
            now,
          ),
        )
        .for("update");
      const passwordHash = await hashSecretForClaimedOtpChallenge(
        challenge,
        () => hashCustomerSecret(parsed.data.newPassword),
      );
      if (passwordHash === null) return { kind: "invalid" } as const;

      const [user] = await tx
        .select({
          id: usersTable.id,
          status: usersTable.status,
          emailVerifiedAt: usersTable.emailVerifiedAt,
        })
        .from(usersTable)
        .where(eq(usersTable.emailLookupHash, emailLookupHash))
        .for("update");

      await tx
        .update(phoneOtpChallengesTable)
        .set({ consumedAt: now })
        .where(eq(phoneOtpChallengesTable.id, challenge.id));

      if (!user || user.status !== "active" || !user.emailVerifiedAt) return { kind: "processed" } as const;

      const [credential] = await tx
        .update(customerCredentialsTable)
        .set({
          passwordHash,
          passwordUpdatedAt: now,
          updatedAt: now,
        })
        .where(eq(customerCredentialsTable.userId, user.id))
        .returning({ userId: customerCredentialsTable.userId });

      if (!credential) return { kind: "processed" } as const;

      await tx
        .update(customerSessionsTable)
        .set({ revokedAt: now, pinVerifiedUntil: null })
        .where(
          and(
            eq(customerSessionsTable.userId, user.id),
            isNull(customerSessionsTable.revokedAt),
          ),
        );

      await clearAuthFailures(authAttemptBuckets, tx);
      return { kind: "processed" } as const;
    });

    if (result.kind === "invalid") {
      res.status(409).json({ error: "La vérification a expiré ou a déjà été utilisée. Demandez un nouveau code." });
      return;
    }

    res.json(ResetCustomerPasswordResponse.parse({ success: true }));
  } catch (error) {
    req.log.error({ errorCode: safeErrorCode(error) }, "Customer password recovery failed");
    res.status(503).json({ error: "La récupération du compte est momentanément indisponible." });
  }
});

router.post("/auth/reset-pin", async (req, res): Promise<void> => {
  if (!isTrustedOrigin(req)) {
    res.status(403).json({ error: "Origine de requête non autorisée." });
    return;
  }

  const parsed = ResetCustomerPinBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Vérifiez les informations de récupération." });
    return;
  }

  const now = new Date();
  try {
    const [availableChallenge] = await db
      .select({ id: phoneOtpChallengesTable.id })
      .from(phoneOtpChallengesTable)
      .where(
        verifiedCustomerOtpCondition(
          parsed.data.challengeId,
          parsed.data.phone,
          "pin_reset",
          now,
        ),
      )
      .limit(1);
    if (!availableChallenge) {
      res.status(409).json({ error: "La vérification a expiré ou a déjà été utilisée. Demandez un nouveau code." });
      return;
    }

    // PIN checks share this user bucket, so acquire it before locking challenge or account rows.
    const [attemptUser] = await db
      .select({ id: usersTable.id })
      .from(usersTable)
      .where(or(
        eq(usersTable.phoneLookupHash, createSensitiveDataLookupIndex(parsed.data.phone, "user-phone")),
        eq(usersTable.phone, parsed.data.phone),
      ))
      .limit(1);
    const pinAttemptBuckets = attemptUser
      ? [getCustomerPinAttemptBucket(attemptUser.id)]
      : [];
    const result = await withPinAttemptLock(pinAttemptBuckets, async (tx) => {
      const [challenge] = await tx
        .select({ id: phoneOtpChallengesTable.id })
        .from(phoneOtpChallengesTable)
        .where(
          verifiedCustomerOtpCondition(
            parsed.data.challengeId,
            parsed.data.phone,
            "pin_reset",
            now,
          ),
        )
        .for("update");
      const pinHash = await hashSecretForClaimedOtpChallenge(
        challenge,
        () => hashCustomerSecret(parsed.data.newPin),
      );
      if (pinHash === null) return { kind: "invalid" } as const;

      const [user] = await tx
        .select({ id: usersTable.id, status: usersTable.status })
        .from(usersTable)
        .where(or(
          eq(usersTable.phoneLookupHash, createSensitiveDataLookupIndex(parsed.data.phone, "user-phone")),
          eq(usersTable.phone, parsed.data.phone),
        ))
        .for("update");

      await tx
        .update(phoneOtpChallengesTable)
        .set({ consumedAt: now })
        .where(eq(phoneOtpChallengesTable.id, challenge.id));

      if (!user || !attemptUser || user.id !== attemptUser.id || user.status !== "active") {
        return { kind: "processed" } as const;
      }

      const [credential] = await tx
        .update(customerCredentialsTable)
        .set({
          pinHash,
          pinUpdatedAt: now,
          updatedAt: now,
        })
        .where(eq(customerCredentialsTable.userId, user.id))
        .returning({ userId: customerCredentialsTable.userId });

      if (!credential) return { kind: "processed" } as const;

      await tx
        .update(customerSessionsTable)
        .set({ revokedAt: now, pinVerifiedUntil: null })
        .where(
          and(
            eq(customerSessionsTable.userId, user.id),
            isNull(customerSessionsTable.revokedAt),
          ),
        );

      await clearAuthFailures(pinAttemptBuckets, tx);
      return { kind: "processed" } as const;
    });

    if (result.kind === "invalid") {
      res.status(409).json({ error: "La vérification a expiré ou a déjà été utilisée. Demandez un nouveau code." });
      return;
    }

    res.json(ResetCustomerPinResponse.parse({ success: true }));
  } catch (error) {
    req.log.error({ errorCode: safeErrorCode(error) }, "Customer PIN recovery failed");
    res.status(503).json({ error: "La récupération du compte est momentanément indisponible." });
  }
});

export default router;